
CREATE TABLE Orders (
    OrderID VARCHAR(20),
    OrderDate DATE,
    Amount DECIMAL(10,2),
    Profit DECIMAL(10,2),
    Quantity INT,
    Category VARCHAR(50),
    SubCategory VARCHAR(50),
    PaymentMode VARCHAR(50)
);

